# Reload sub.json and implement the algorithm correctly
with open("/home/USER/runs/paper/qwen-in-glm-h-u1/frozen/held-out-5/play/users/u001/system/state/workspace/sub.json", 'r') as f:
    sub = json.load(f)
    grid = sub['grid']

h, w = len(grid), len(grid[0])
print(f"Grid: {h}x{w}")

# 3x3 block downsample
div_h, div_w = 3, 3
out_h, out_w = h // div_h, w // div_w

def majority_non_5(block):
    """Return majority non-5 color, or 0 if only 5s present"""
    counts = {}
    for row in block:
        for cell in row:
            if cell != 5:
                counts[cell] = counts.get(cell, 0) + 1
    if not counts:
        return 0
    return max(counts, key=counts.get)

output = []
for r in range(out_h):
    row_out = []
    for c in range(out_w):
        block = grid[r*3:(r+1)*3][c*3:(c+1)*3]
        row_out.append(majority_non_5(block))
    output.append(row_out)

print("\nOutput grid:")
for row in output:
